    perm_matrix = [[0 for _ in range(n)] for _ in range(n)]
    det_matrix = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if (i+1) * (j+1) % 2 == 0:
                perm_matrix[i][j] = M[i][j]
            else:
