def primes(n):
    sieve = [True] * (n+1)
    for x in range(2, int(n**0.5) + 1):
        if sieve[x]:
            for i in range(x*x, n+1, x):
                sieve[i] = False
    return [x for x in range(2, n+1) if sieve[x]]

import random
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def matrix_mult(A, B):
    m, n, p = len(A), len(B), len(B[0])
    C = [[0] * p for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def matrix_power(A, k):
    n = len(A)
    result = [[0 if i != j else 1 for j in range(n)] for i in range(n)]
    while k:
        if k % 2 == 1:
            result = matrix_mult(result, A)
        A = matrix_mult(A, A)
        k //= 2
    return result

def gaussian_elimination(A):
    n = len(A)
    rank = 0
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        if A[i][i] == 0:
            continue
        rank += 1
        for j in range(i+1, n):
            factor = A[j][i] / A[i][i]
            for k in range(n):
                A[j][k] -= factor * A[i][k]
    return rank

def trivial_representation_multiplicity(A):
    return gaussian_elimination(A)

def generate_random_3cnf(n):
    clauses = []
    for _ in range(10*n):
        clause = [random.choice([-1, 1]) * random.randint(1, n) for _ in range(3)]
        if len(set(clause)) == 3:
            clauses.append(clause)
    return clauses

def permanent_polynomial(clauses):
    n = max(abs(x) for x in sum(clauses, []))
    A = [[0] * (n+1) for _ in range(n+1)]
    for clause in clauses:
        for x in clause:
            if x > 0:
                A[x-1][x] += 1
            else:
                A[-x-1][-x] += 1
    return matrix_power(A, n)[0][n]

