from fractions import Fraction

def gaussian_elimination(A, b):
    n = len(A)
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        b[i], b[max_row] = b[max_row], b[i]
        pivot = A[i][i]
        for j in range(i, n):
            A[i][j] /= pivot
        b[i] /= pivot
        for j in range(n):
            if i != j:
                factor = A[j][i]
                for k in range(i, n):
                    A[j][k] -= factor * A[i][k]
                b[j] -= factor * b[i]

def is_independent_system(A, b):
    gaussian_elimination(A, b)
    for i in range(len(b)):
        if abs(b[i]) > 1e-9:
            return False
    return True

def trivial_representation_multiplicity(P, n):
    A = [[0] * (n+1) for _ in range(n+1)]
    b = [0] * (n+1)
    for i in range(1, n+1):
        for j in range(1, n+1):
            if P[i-1][j-1] == 1:
                A[i][j] = 1
                b[j] += 1
    return is_independent_system(A, b)

def perm_n(n):
    def perm(a, i, j):
        a[i], a[j] = a[j], a[i]

    def generate_perms(a, start, end):
        if start == end:
            yield list(a)
        else:
            for i in range(start, end+1):
                perm(a, start, i)
                yield from generate_perms(a, start+1, end)
                perm(a, start, i)

    return list(generate_perms(list(range(1, n+1)), 0, n-1))

def symmetric_power(P, n):
    result = [[0] * n for _ in range(n)]
    perms = perm_n(n)
    for p in perms:
        for i in range(n):
            for j in range(n):
                if P[i][p[j]-1] == 1 and P[p[i]-1][j] == 1:
                    result[i][j] += 1
    return result

